/*
 * prog17_whitespace_trim.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 *
 * The program receives a single command‑line argument.  It trims leading
 * whitespace, collapses any run of whitespace characters (space, tab,
 * newline, vertical‑tab, form‑feed, carriage‑return) to a single space,
 * and removes a trailing space if one would be produced.  The input is
 * processed at most 1024 characters – longer strings are silently
 * truncated.  If the resulting string is empty (or no argument was
 * supplied) the program prints the literal word “EMPTY”.
 *
 * The behaviour matches the de‑compiled control‑flow of the supplied
 * binary while being expressed in clear, idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024          /* maximum characters taken from argv[1] */
#define OUT_BUF   (MAX_INPUT+1) /* space for the terminating NUL */

int main(int argc, char **argv)
{
    const char *src;
    char out[OUT_BUF];
    size_t out_len = 0;
    int have_output = 0;   /* have we written any non‑whitespace yet? */
    int space_pending = 0; /* a space has been emitted for the current run */

    /* No argument → “EMPTY”. */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    src = argv[1];
    size_t len = strlen(src);
    if (len > MAX_INPUT)
        len = MAX_INPUT;               /* truncate overly long inputs */

    for (size_t i = 0; i < len; ++i) {
        unsigned char ch = (unsigned char)src[i];

        if (isspace(ch)) {
            /* Skip leading whitespace. */
            if (!have_output)
                continue;

            /* Emit a single space for the first whitespace character
               of a run; subsequent whitespace characters are ignored. */
            if (!space_pending) {
                out[out_len++] = ' ';
                space_pending = 1;
            }
        } else {
            /* Normal (non‑whitespace) character. */
            out[out_len++] = ch;
            have_output   = 1;
            space_pending = 0;          /* reset for the next run */
        }
    }

    /* Remove a trailing space that could have been produced by a final
       run of whitespace characters. */
    if (out_len > 0 && out[out_len - 1] == ' ')
        --out_len;

    out[out_len] = '\0';

    if (out_len == 0)
        puts("EMPTY");
    else
        puts(out);

    return 0;
}
